#!/bin/sh
# Confirms a deployment was generated by the Node build inside Cloudflare at local HEAD.
# usage: scripts/verify.sh https://geeked.gg   (or a *.pages.dev preview URL)
set -e
URL=${1:?usage: verify.sh <site-url>}
URL=${URL%/}
json=$(curl -fsS "$URL/build.json")
remote=$(printf '%s' "$json" | sed -n 's/.*"commit":"\([0-9a-f]*\)".*/\1/p')
source=$(printf '%s' "$json" | sed -n 's/.*"source":"\([a-z]*\)".*/\1/p')
local=$(git rev-parse HEAD)
echo "deployed: ${remote:-<none>} (${source:-?})"
echo "local:    $local"
[ "$source" = cloudflare ] || { echo "FAIL: deployment was not stamped by a Cloudflare build"; exit 1; }
[ "$remote" = "$local" ] || { echo "FAIL: deployment is not at local HEAD"; exit 1; }
echo "OK: $URL was generated by the Node build at $local"
